import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Arrow-First Language Kernel","description":"","frontmatter":{},"headers":[],"relativePath":"handl/PAPER.md","filePath":"vendored/handl/PAPER.md"}`),a={name:`handl/PAPER.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="arrow-first-language-kernel" tabindex="-1">Arrow-First Language Kernel <a class="header-anchor" href="#arrow-first-language-kernel" aria-label="Permalink to “Arrow-First Language Kernel”">​</a></h1><blockquote><p>This paper presents the arrow-first thesis. The normative kernel design is <a href="https://github.com/handl-lang/host/blob/project/adrs/0106-object-arrow-kernel.md" target="_blank" rel="noreferrer">ADR-0106: the object/arrow kernel</a>, which folds the arrow calculus into a single object world (<code>sym()</code>/<code>sym(A)</code>, arrows, and <code>&lt;&gt;</code> dimensions). The graded arrow is written <code>A ~[R]~&gt; B</code> in both the ADR and the canonical grammar (the legacy <code>A ~R~&gt; B</code> shorthand is still accepted).</p><p>The kernel presented here is the dimension-1 fragment of a more general design: <a href="https://github.com/handl-lang/host/blob/main/research/PAPER.md" target="_blank" rel="noreferrer">the N-dimensional arrow calculus</a> generalizes <code>A ~&gt; B</code> to n-morphisms <code>A ~[n]~&gt; B</code>, distinguishes morphism dimension from composition axis (<code>&gt;&gt;&gt;[k]</code> — the <code>&gt;&gt;&gt;</code> of this paper is <code>&gt;&gt;&gt;[0]</code> at dimension 1), and treats laws and proofs as higher morphisms rather than a separate rule language. None of the claims below change; the n-dimensional paper is an upward extension, not a revision.</p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to “Abstract”">​</a></h2><p>This paper proposes a programming language whose fundamental computational abstraction is the <strong>arrow</strong>, rather than the function, and whose language definition is itself a <strong>first-class value</strong>.</p><p>An arrow <code>A ~&gt; B</code> is a first-class description of a computation from <code>A</code> to <code>B</code>. Computations are constructed compositionally using an Arrow Calculus; their meaning is supplied separately by <strong>handlers</strong>. The kernel is six primitives — <code>arr</code>, <code>&gt;&gt;&gt;</code>, <code>first</code>, <code>choice</code>, <code>loop</code>, <code>app</code> — the first three forming the minimal Arrow structure, the latter three providing branching, feedback, and higher-order computation.</p><p>Two principles organize the design:</p><blockquote><p><strong>The kernel constructs computations; handlers interpret them.</strong></p></blockquote><p>Execution is therefore one possible interpretation of a program, not a primitive property of it. The same arrow may be compiled, analyzed, optimized, tested, or otherwise interpreted.</p><blockquote><p><strong>If programs are first-class arrows, then the language that defines those programs should itself be a first-class value.</strong></p></blockquote><p>Making the language first-class has the same effect that making functions/arrows first-class had: capabilities that previously lived outside the language — lexing, parsing, typechecking, formatting, compiling, debugging — become ordinary values that can be composed, passed around, transformed, and interpreted.</p><hr><h2 id="_1-arrow-as-the-fundamental-computational-value" tabindex="-1">1. Arrow as the Fundamental Computational Value <a class="header-anchor" href="#_1-arrow-as-the-fundamental-computational-value" aria-label="Permalink to “1. Arrow as the Fundamental Computational Value”">​</a></h2><p>The fundamental computational type is:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>A ~&gt; B</span></span></code></pre></div><p>rather than:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>A =&gt; B</span></span></code></pre></div><p>An arrow is not primarily a function to be called. It is a compositional computational object.</p><p>For example:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>parse</span></span>
<span class="line"><span>&gt;&gt;&gt; validate</span></span>
<span class="line"><span>&gt;&gt;&gt; compile</span></span></code></pre></div><p>constructs a larger arrow. Composition does not imply execution.</p><hr><h2 id="_2-the-kernel" tabindex="-1">2. The Kernel <a class="header-anchor" href="#_2-the-kernel" aria-label="Permalink to “2. The Kernel”">​</a></h2><h3 id="arr" tabindex="-1"><code>arr</code> <a class="header-anchor" href="#arr" aria-label="Permalink to “arr”">​</a></h3><p>Introduces primitive/pure computation into the arrow calculus.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>arr f : A ~&gt; B</span></span></code></pre></div><h3 id="" tabindex="-1"><code>&gt;&gt;&gt;</code> <a class="header-anchor" href="#" aria-label="Permalink to “&gt;&gt;&gt;”">​</a></h3><p>Sequentially composes arrows:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>a : A ~&gt; B</span></span>
<span class="line"><span>b : B ~&gt; C</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a &gt;&gt;&gt; b : A ~&gt; C</span></span></code></pre></div><p>It is the fundamental flow operation.</p><h3 id="first" tabindex="-1"><code>first</code> <a class="header-anchor" href="#first" aria-label="Permalink to “first”">​</a></h3><p>Lifts an arrow over product structure:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>f : A ~&gt; B</span></span>
<span class="line"><span></span></span>
<span class="line"><span>first f : (A, X) ~&gt; (B, X)</span></span></code></pre></div><p>This provides the basic mechanism for structured data flow.</p><h3 id="choice" tabindex="-1"><code>choice</code> <a class="header-anchor" href="#choice" aria-label="Permalink to “choice”">​</a></h3><p>Provides branching over alternatives:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>f : A ~&gt; C</span></span>
<span class="line"><span>g : B ~&gt; C</span></span>
<span class="line"><span></span></span>
<span class="line"><span>choice f g : A + B ~&gt; C</span></span></code></pre></div><p>This supports conditionals, pattern matching, error paths, and other branching structures.</p><h3 id="loop" tabindex="-1"><code>loop</code> <a class="header-anchor" href="#loop" aria-label="Permalink to “loop”">​</a></h3><p>Provides feedback:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>f : (A, S) ~&gt; (B, S)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>loop f : A ~&gt; B</span></span></code></pre></div><p>The <code>S</code> channel is fed back into the computation. The fundamental concept is <strong>feedback</strong>, not <code>while</code>. Iteration and state machines can be derived from feedback.</p><h3 id="app" tabindex="-1"><code>app</code> <a class="header-anchor" href="#app" aria-label="Permalink to “app”">​</a></h3><p>Provides dynamic/higher-order arrow application (<code>ArrowApply</code> in the Haskell hierarchy). It allows an arrow to receive another arrow as data and invoke it during computation. This is distinct from interpreting an entire arrow externally — <code>app</code> is a calculus operation <em>within</em> a computation; a handler interprets the computation <em>from outside</em>.</p><p><code>app</code> is not part of the minimal Arrow calculus (Lindley–Wadler–Yallop); it is an extension. We include it because the language requires higher-order arrows — arrows that can dynamically invoke other arrows received as runtime data. Whether this is necessary is a language-design choice, not something established by the Arrow literature.</p><hr><h2 id="_3-construction-vs-interpretation" tabindex="-1">3. Construction vs Interpretation <a class="header-anchor" href="#_3-construction-vs-interpretation" aria-label="Permalink to “3. Construction vs Interpretation”">​</a></h2><p>The kernel constructs arrow programs:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>program =</span></span>
<span class="line"><span>    parse</span></span>
<span class="line"><span>    &gt;&gt;&gt; validate</span></span>
<span class="line"><span>    &gt;&gt;&gt; compile</span></span></code></pre></div><p>A handler gives the program an interpretation:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>handle Runtime program</span></span>
<span class="line"><span>handle Compiler program</span></span>
<span class="line"><span>handle Analyzer program</span></span></code></pre></div><p>Thus:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>arrow       = computational description</span></span>
<span class="line"><span>handler     = interpretation</span></span></code></pre></div><p>Execution is not a primitive property of arrows. A runtime handler performs I/O; a test handler provides deterministic substitutes; a compiler handler produces machine code; an analyzer inspects effects without executing them. The computational description remains unchanged.</p><h3 id="effects-and-handlers" tabindex="-1">Effects and handlers <a class="header-anchor" href="#effects-and-handlers" aria-label="Permalink to “Effects and handlers”">​</a></h3><p>Effectful primitives are operations in the arrow computation. A handler determines their semantics. We adopt the handler model of Sanada&#39;s <em>Algebraic Effects and Handlers for Arrows</em> as the semantic foundation: an operation handler receives the operation&#39;s argument and its continuation, defining how the operation is interpreted and how computation resumes. Sanada provides operational semantics (proved sound and adequate) and a denotational semantics in which handlers are homomorphisms between algebras of arrows.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Arrow       = what computation is described</span></span>
<span class="line"><span>Operation   = what effect is requested</span></span>
<span class="line"><span>Handler     = how that effect is interpreted</span></span></code></pre></div><hr><h2 id="_4-first-class-programs-and-languages" tabindex="-1">4. First-Class Programs and Languages <a class="header-anchor" href="#_4-first-class-programs-and-languages" aria-label="Permalink to “4. First-Class Programs and Languages”">​</a></h2><h3 id="programs-are-values" tabindex="-1">Programs are values <a class="header-anchor" href="#programs-are-values" aria-label="Permalink to “Programs are values”">​</a></h3><p>Because arrows are values, programs can themselves be transformed:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>optimize : Program ~&gt; Program</span></span>
<span class="line"><span>analyze  : Program ~&gt; Analysis</span></span>
<span class="line"><span>compile  : Program ~&gt; MachineCode</span></span></code></pre></div><p>This makes compiler passes, optimizers, analyzers, and language tooling ordinary computations over computational objects. The distinction between program, compiler, optimizer, and interpreter becomes less fundamental — they are all computations that can themselves be represented and manipulated.</p><h3 id="languages-are-values" tabindex="-1">Languages are values <a class="header-anchor" href="#languages-are-values" aria-label="Permalink to “Languages are values”">​</a></h3><p>If programs are first-class arrows, then the language that defines those programs should itself be a first-class value.</p><p>Making functions first-class turned functions from a compiler-internal concept into values that could be passed, stored, composed, and returned. Making arrows first-class turned computations from an execution-time concept into values that can be inspected, transformed, and interpreted. Making the <strong>language</strong> first-class turns the language itself — its lexer, parser, typechecker, formatter, compiler, debugger — from external infrastructure into values that can be composed, passed around, transformed, and interpreted.</p><p>A language is a first-class value:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Language</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├── lex</span></span>
<span class="line"><span>   ├── parse</span></span>
<span class="line"><span>   ├── evaluate</span></span>
<span class="line"><span>   ├── format</span></span>
<span class="line"><span>   ├── lint</span></span>
<span class="line"><span>   ├── typecheck</span></span>
<span class="line"><span>   ├── proofcheck</span></span>
<span class="line"><span>   ├── debug</span></span>
<span class="line"><span>   ├── profile</span></span>
<span class="line"><span>   ├── compile</span></span>
<span class="line"><span>   ├── optimize</span></span>
<span class="line"><span>   ├── transform</span></span>
<span class="line"><span>   └── visualize</span></span></code></pre></div><p>These are not bespoke features of a host language. They are <strong>generic tooling protocols</strong> that any language implementing the protocol can participate in. A typechecker is not a privileged compiler pass — it is a handler over a language value. A new language is not a new toolchain — it is a new value of type <code>Language</code>, and every conforming tool works on it immediately.</p><h3 id="the-hierarchy" tabindex="-1">The hierarchy <a class="header-anchor" href="#the-hierarchy" aria-label="Permalink to “The hierarchy”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>values</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>arrows              ← first-class computations</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>programs            ← arrows describing programs</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>languages           ← first-class values describing how programs work</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>generic tooling     ← operates on any conforming language</span></span></code></pre></div><p>Each level is a first-class value at the level below it. Arrows are values. Programs are arrows. Languages are values describing how programs work. Generic tooling operates on any conforming language.</p><p>This is the route to a self-hosting, reflective computational environment where the distinction between program, compiler, DSL, and language implementation is deliberately minimized — not by fiat, but because they are all the same kind of thing: first-class values interpreted by handlers.</p><h3 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h3><p>Four consequences follow from making both arrows and languages first-class:</p><ul><li><p><strong>Language becomes first-class.</strong> <code>currentLanguage</code> is accessible inside programs; languages can be inspected, composed, extended, and used to lex/parse/evaluate themselves.</p></li><li><p><strong>Tooling becomes generic.</strong> Formatter, linter, typechecker, proofchecker, debugger, profiler, compiler, optimizer, transformer, visualizer, etc. operate through a common <code>Language</code> protocol — not as per-language infrastructure.</p></li><li><p><strong>Functions become derived.</strong> <code>A → B</code> is the pure/simplest case of <code>A ~&gt; B</code>. Hughes shows that ordinary functions form an Arrow instance (<code>arr f = f</code>, with composition and <code>first</code> defined naturally), so one uniform model covers pure functions, effectful arrows, stateful arrows, branching arrows, and higher-order arrows without two foundational worlds needing bridges between them. This is a <strong>language-design choice inspired by the Arrow theory</strong>: the literature supports that functions <em>can</em> be an Arrow instance, not that they <em>should</em> be eliminated as a separate type. The Arrow Calculus itself (Lindley–Wadler–Yallop) is formulated by extending simply typed lambda calculus with arrow constructs. Our language chooses to make arrows primary and treat functions as the degenerate pure case.</p></li><li><p><strong>Parametric arrows</strong> become the abstraction for computations over computations:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Arrow&lt;A, B&gt; → Arrow&lt;C, D&gt;</span></span></code></pre></div><p>An optimizer, a compiler, an analyzer, or a language transformer is an arrow whose input and output are themselves arrows. This is the meta-level of the calculus — and it is not a separate meta-language; it is the same calculus, applied to arrow-valued data.</p></li></ul><hr><h2 id="_5-a-sketch-of-the-language" tabindex="-1">5. A Sketch of the Language <a class="header-anchor" href="#_5-a-sketch-of-the-language" aria-label="Permalink to “5. A Sketch of the Language”">​</a></h2><h3 id="programs-are-data" tabindex="-1">Programs are data <a class="header-anchor" href="#programs-are-data" aria-label="Permalink to “Programs are data”">​</a></h3><p>A primitive arrow:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>add : (Int, Int) ~&gt; Int</span></span></code></pre></div><p>Arrow composition:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>double : Int ~&gt; Int =</span></span>
<span class="line"><span>    x =&gt; x + x</span></span>
<span class="line"><span></span></span>
<span class="line"><span>program : Int ~&gt; Int =</span></span>
<span class="line"><span>    double</span></span>
<span class="line"><span>    &gt;&gt;&gt; add(10)</span></span></code></pre></div><p>The important part is that <strong><code>program</code> is data</strong>:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>program</span></span>
<span class="line"><span>// Arrow&lt;Int, Int&gt;</span></span></code></pre></div><p>You can transform it:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>optimized = optimize(program)</span></span>
<span class="line"><span>formatted = format(program)</span></span>
<span class="line"><span>graph     = visualize(program)</span></span></code></pre></div><h3 id="the-language-is-also-a-value" tabindex="-1">The language is also a value <a class="header-anchor" href="#the-language-is-also-a-value" aria-label="Permalink to “The language is also a value”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>lang : Language</span></span></code></pre></div><p>You can access its capabilities:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>tokens = lang.lex(source)</span></span>
<span class="line"><span>ast    = lang.parse(tokens)</span></span>
<span class="line"><span>result = lang.evaluate(ast)</span></span>
<span class="line"><span>pretty = lang.format(ast)</span></span>
<span class="line"><span>errors = lang.lint(ast)</span></span>
<span class="line"><span>types  = lang.typecheck(ast)</span></span>
<span class="line"><span>trace  = lang.debug(ast)</span></span></code></pre></div><h3 id="manipulating-the-language-itself" tabindex="-1">Manipulating the language itself <a class="header-anchor" href="#manipulating-the-language-itself" aria-label="Permalink to “Manipulating the language itself”">​</a></h3><p>You can manipulate the language itself:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>newLang =</span></span>
<span class="line"><span>    lang</span></span>
<span class="line"><span>    &gt;&gt;&gt; addSyntax(...)</span></span>
<span class="line"><span>    &gt;&gt;&gt; addPrimitive(...)</span></span>
<span class="line"><span>    &gt;&gt;&gt; addType(...)</span></span></code></pre></div><p>and then use the resulting language:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>ast    = newLang.parse(source)</span></span>
<span class="line"><span>result = newLang.evaluate(ast)</span></span></code></pre></div><h3 id="the-self-hosting-loop" tabindex="-1">The self-hosting loop <a class="header-anchor" href="#the-self-hosting-loop" aria-label="Permalink to “The self-hosting loop”">​</a></h3><p>The language can be available <strong>from inside programs written in that language</strong>:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>language = currentLanguage</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ast  = language.parse(source)</span></span>
<span class="line"><span>ast2 = transform(ast)</span></span>
<span class="line"><span>language.evaluate(ast2)</span></span></code></pre></div><h3 id="the-full-architecture" tabindex="-1">The full architecture <a class="header-anchor" href="#the-full-architecture" aria-label="Permalink to “The full architecture”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>                 Language</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>       ┌────────────┼────────────┐</span></span>
<span class="line"><span>       │            │            │</span></span>
<span class="line"><span>      lex          parse       evaluate</span></span>
<span class="line"><span>       │            │            │</span></span>
<span class="line"><span>       └────────────┼────────────┘</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                   AST</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>       ┌────────────┼────────────┐</span></span>
<span class="line"><span>       │            │            │</span></span>
<span class="line"><span>    transform    optimize      format</span></span>
<span class="line"><span>       │            │            │</span></span>
<span class="line"><span>       └────────────┼────────────┘</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                 Program</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                  Arrow</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                 handler</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>       ┌────────────┼────────────┐</span></span>
<span class="line"><span>       │            │            │</span></span>
<span class="line"><span>     runtime      compiler     analyzer</span></span></code></pre></div><p>And <strong>all of those are themselves values/computations</strong>.</p><p>That is the distinctive part: not merely <em>first-class ASTs</em>, but <strong>first-class languages whose generic protocol exposes lexing, parsing, evaluation, and tooling</strong>.</p><p>The language is therefore not just the thing that runs the program.</p><p><strong>The language is another object the program can compute with.</strong></p><hr><h2 id="_6-lineage" tabindex="-1">6. Lineage <a class="header-anchor" href="#_6-lineage" aria-label="Permalink to “6. Lineage”">​</a></h2><p>This proposal does not invent a calculus; it adopts two mature lineages and combines them.</p><table tabindex="0"><thead><tr><th>Work</th><th>Contribution</th><th>Relevance</th></tr></thead><tbody><tr><td><strong>Moggi</strong> — <em>Notions of Computation and Monads</em> (1991)</td><td>Computational effects via monads; the monadic metalanguage. The precursor that Hughes generalizes.</td><td>Computational effects foundation</td></tr><tr><td><strong>Hughes (2000)</strong> — <em>Generalising Monads to Arrows</em></td><td>Introduced <strong>arrows</strong> as a generalization of monads; the minimal <code>arr</code>, <code>&gt;&gt;&gt;</code>, <code>first</code>.</td><td>Computational abstraction</td></tr><tr><td><strong>Paterson (2001)</strong> — <em>A New Notation for Arrows</em></td><td>Added practical <strong>arrow notation</strong> (<code>proc</code>), making point-free arrow programs readable and compositional; introduced <strong><code>loop</code></strong> (feedback) and <code>returnA</code>.</td><td>Surface syntax + feedback</td></tr><tr><td><strong>Lindley, Wadler, Yallop (2008/2010)</strong> — <em>The Arrow Calculus</em></td><td>Made arrows into a genuine <strong>Arrow Calculus</strong>: a typed metalanguage for manipulating Hughes&#39;s arrows. Four constructs, five laws, proved complete.</td><td>Calculus / language foundation</td></tr><tr><td><strong>Lindley, Wadler, Yallop (2011)</strong> — <em>Idioms are Oblivious, Arrows are Meticulous, Monads are Promiscuous</em></td><td>Placed arrows in the landscape of monads/idioms/arrows; showed classic arrows and the Arrow Calculus are equationally corresponding.</td><td>Algebraic grounding</td></tr><tr><td><strong>Lindley (2014)</strong> — <em>Algebraic Effects and Effect Handlers for Idioms and Arrows</em></td><td>Generalized algebraic effects and handlers to idioms and arrows; established that handlers aren&#39;t inherently tied to monadic computation.</td><td>Effects + handlers for arrows</td></tr><tr><td><strong>Sanada (2024)</strong> — <em>Algebraic Effects and Handlers for Arrows</em></td><td>Formalized <strong>Arrow Calculus with operations and handlers</strong>, with operational + denotational semantics; handlers correspond to homomorphisms of arrow algebras; proves soundness and adequacy.</td><td>Semantic foundation for our handlers</td></tr><tr><td><strong>Cimini (2018/2022)</strong> — <em>A Calculus for Multi-language Operational Semantics</em></td><td>Presents <code>λ^𝓛</code>, a typed λ-calculus where <strong>languages are first-class citizens</strong>: bound to variables, passed to functions, returned from functions, used to execute programs.</td><td>Languages as first-class values</td></tr></tbody></table><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Moggi</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ computational effects / monadic metalanguage</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Hughes (2000)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ arrows</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Paterson (2001)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ arrow notation + feedback</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Lindley / Wadler / Yallop (2008–10)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ Arrow Calculus</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Lindley / Wadler / Yallop (2011)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ arrows in the monad/applicative/arrow landscape</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Lindley (2014)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ effects + handlers for arrows</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Sanada (2024)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ formal operational + denotational</span></span>
<span class="line"><span>  │ semantics for arrow handlers</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Cimini (2018/2022)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ languages as first-class values</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Our language</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ Arrow-first + Language-first</span></span>
<span class="line"><span>  ▼</span></span></code></pre></div><p>Our key step combines two lineages:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Arrow lineage:                    Language-as-value lineage:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hughes → Paterson → LWY           Cimini</span></span>
<span class="line"><span>  → Lindley → Sanada                languages as</span></span>
<span class="line"><span>  Arrow Calculus                    first-class values</span></span>
<span class="line"><span>  + handlers                        + operational semantics</span></span>
<span class="line"><span>       │                                 │</span></span>
<span class="line"><span>       └──────────────┬──────────────────┘</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>               Our language</span></span>
<span class="line"><span>               Arrow-first + Language-first</span></span></code></pre></div><p>The precise formulation of our contribution:</p><blockquote><p><strong>Cimini makes languages first-class inside a general-purpose language. We make the Arrow Calculus the computational substrate of such a language, while treating the language itself as a first-class computational value.</strong></p></blockquote><p>The three first-class transformations are symmetrical:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Function → first-class</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>computation becomes manipulable data</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Arrow → first-class</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>computation descriptions become manipulable data</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Language → first-class</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>the rules for constructing/interpreting</span></span>
<span class="line"><span>those computations become manipulable data</span></span></code></pre></div><p>That last step is what makes the architecture substantially more powerful than merely having a reflective AST API.</p><p>The important difference is that <strong>we aren&#39;t embedding arrows inside a conventional functional language</strong>. We&#39;re making the Arrow Calculus itself the computational substrate, with Sanada&#39;s handler semantics providing the foundation for interpretation — and making the language itself a first-class value (Cimini&#39;s insight) whose tooling operations are themselves arrows.</p><hr><h2 id="_7-use-cases" tabindex="-1">7. Use Cases <a class="header-anchor" href="#_7-use-cases" aria-label="Permalink to “7. Use Cases”">​</a></h2><p>The architectural properties of an Arrow Calculus kernel — programs as first-class descriptions, interpretation delegated to handlers, languages as first-class values, no serialization tax, structural capability tracking — make it well-suited to several concrete use cases that are awkward in conventional lambda-first languages.</p><h3 id="no-serialization-tax" tabindex="-1">No serialization tax <a class="header-anchor" href="#no-serialization-tax" aria-label="Permalink to “No serialization tax”">​</a></h3><p>In a conventional language, a program is an in-memory AST or closure graph. To send it across a process boundary, store it, or hand it to a different runtime, you serialize it (to JSON, protobuf, bytecode) and deserialize it on the other side. This is a tax: every cross-boundary interaction pays a formatting and parsing cost, and the deserialized form is a <em>different object</em> from the original — it has lost structure, identity, or both.</p><p>In an Arrow Calculus language, the arrow <em>is</em> data. The kernel is six serializable primitives; an arrow is a first-class description that can be stored, transmitted, and loaded without a separate serialization layer. The same value that the runtime interprets is the value that crosses the boundary.</p><p>This matters for:</p><ul><li><strong>Web performance.</strong> A server can send an arrow (a computation) to a client, and the client interprets it directly — no JSON parse, no AST rebuild, no separate &quot;client runtime&quot; that reconstructs the program. The arrow is the wire format. This eliminates a round of serialization on every server-to-client computation transfer, which is the dominant cost in data-heavy web applications.</li><li><strong>Game modding performance.</strong> A game engine can load a mod as an arrow description and interpret it directly, without compiling the mod to a separate bytecode and without a per-mod AST-to-bytecode pipeline. Mods load fast; the engine&#39;s handler interprets them; the same arrow can be inspected for capability/safety before interpretation.</li><li><strong>Distributed computation.</strong> A computation can migrate between nodes without a marshalling layer. The arrow is the portable form; each node&#39;s handler interprets it locally.</li></ul><h3 id="sandboxing" tabindex="-1">Sandboxing <a class="header-anchor" href="#sandboxing" aria-label="Permalink to “Sandboxing”">​</a></h3><p>Because an arrow is a first-class description with structural capability tracking (foreign operations are tagged, not a string convention), a host can inspect an arrow <em>before</em> interpreting it and decide whether to allow it. Sandboxing is interpretation-time policy, not a property the program must opt into.</p><p>This matters for:</p><ul><li><strong>Untrusted scripts.</strong> A host receives an arrow from an untrusted source, inspects its operations (does it call <code>fs.read</code>? <code>net.connect</code>? <code>process.exit</code>?), and either rejects it, rewrites it, or interprets it under a restricted handler that refuses unauthorized operations. The program cannot bypass the sandbox because the sandbox <em>is</em> the handler — there is no &quot;escape&quot; primitive in the kernel for the program to exploit.</li><li><strong>Untrusted game mods.</strong> A game engine loads a community mod as an arrow, inspects it for forbidden operations, and interprets it under a handler that enforces the policy. The mod author writes in the same language as the engine; the sandbox is a handler choice, not a separate &quot;safe subset&quot; of the language.</li><li><strong>Plugin systems.</strong> A host application accepts third-party plugins as arrows, inspects them for required capabilities, and interprets them under a handler that grants exactly those capabilities and no more.</li></ul><h3 id="first-class-languages-and-dsls" tabindex="-1">First-class languages and DSLs <a class="header-anchor" href="#first-class-languages-and-dsls" aria-label="Permalink to “First-class languages and DSLs”">​</a></h3><p>Because a language is a first-class value that implements tooling protocols, a host can define, extend, compose, and interpret domain-specific languages without a separate meta-language or compiler infrastructure.</p><p>This matters for:</p><ul><li><strong>Embedded DSLs.</strong> A DSL is a language value — a set of primitives plus the six combinators, plus implementations of the tooling protocols. Every conforming tool (formatter, linter, debugger) works on it immediately, because the tool operates on the protocol, not on a language-specific AST.</li><li><strong>Programmable tools.</strong> A linter, formatter, or typechecker is a handler over a language value. Tools are not external infrastructure; they are interpretations of the tooling protocols a language implements. A spatial backend&#39;s runtime tracer (e.g., mapping Stage 1 wire execution back to Stage 0 source blocks in the Staged Arrow Engine) is the same kind of object: a <code>debug</code>/<code>visualize</code> handler over the language value, not a bespoke debugger built per-backend.</li><li><strong>Self-hosting.</strong> The language&#39;s own compiler and optimizer are arrows, interpreted by the same kernel. The language&#39;s own tooling is a language value. This is the route to a self-hosting, reflective computational environment without a separate meta-language.</li></ul><h3 id="multi-target-compilation" tabindex="-1">Multi-target compilation <a class="header-anchor" href="#multi-target-compilation" aria-label="Permalink to “Multi-target compilation”">​</a></h3><p>Because compilation is a handler interpretation, the same arrow description can be lowered to multiple targets without changing the source program.</p><p>This matters for:</p><ul><li><strong>Cross-platform deployment.</strong> One arrow, multiple backends (native, WASM, JavaScript, bytecode, and — per the Staged Arrow Engine proposal — WebGPU/WGSL compute shaders and FPGA netlists via static spatial graph lowering). The source is target-independent; the handler chooses the target.</li><li><strong>Incremental compilation.</strong> A compiler handler can cache lowerings of sub-arrows and recompile only what changed, because the arrow structure is inspectable and referentially stable.</li></ul><hr><h2 id="_8-arrow-calculus-vs-lambda-calculus" tabindex="-1">8. Arrow Calculus vs Lambda Calculus <a class="header-anchor" href="#_8-arrow-calculus-vs-lambda-calculus" aria-label="Permalink to “8. Arrow Calculus vs Lambda Calculus”">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Lambda Calculus</th><th>Arrow Calculus</th></tr></thead><tbody><tr><td>Primitive computation</td><td>Function</td><td>Arrow</td></tr><tr><td>Core operation</td><td>Application</td><td>Composition</td></tr><tr><td>Primary abstraction</td><td>Lambda</td><td>Computational construction</td></tr><tr><td>Data flow</td><td>Implicit</td><td>Explicit</td></tr><tr><td>Program representation</td><td>Usually external</td><td>Native first-class value</td></tr><tr><td>Interpretation</td><td>Usually execution</td><td>Explicit handler</td></tr><tr><td>Transformation</td><td>Meta-level / common tooling</td><td>Language-level operation</td></tr><tr><td>Compiler</td><td>External infrastructure</td><td>Possible arrow / handler</td></tr><tr><td>DSL representation</td><td>Often AST / library</td><td>Native computational object</td></tr><tr><td>Effects</td><td>Usually layered</td><td>Intrinsic to arrows; handler-interpreted</td></tr><tr><td>Recursion</td><td>Primitive (<code>fix</code>, Y-combinator)</td><td>Derived from feedback (<code>loop</code>)</td></tr><tr><td>Language definition</td><td>External / fixed</td><td>First-class value</td></tr><tr><td>Tooling</td><td>Per-language / bespoke</td><td>Generic protocols over any conforming language</td></tr></tbody></table><p>The point is not that one calculus is universally superior. They optimize for different conceptual centers: Lambda Calculus centers <strong>abstraction and substitution</strong>; Arrow Calculus centers <strong>construction and interpretation</strong>.</p><p>Lambda-like functionality does not disappear — it becomes a derived construct. Parameterized computations may still be expressed with syntax resembling <code>x ~&gt; x + 1</code>, but the semantic object produced is <code>Int ~&gt; Int</code>, an arrow, rather than a primitive function closure. Higher-order behavior is expressed via <code>app</code>:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>app : ((A ~&gt; B), A) ~&gt; B</span></span></code></pre></div><p>This is a language-design choice, not a claim established by the Arrow literature. The Arrow Calculus (Lindley–Wadler–Yallop) is itself formulated by extending simply typed lambda calculus with arrow constructs; the literature shows that functions <em>can</em> be an Arrow instance (Hughes), not that a language <em>should</em> eliminate functions as a separate type. Our language chooses to make arrows the primary computational abstraction, with pure functions represented as the degenerate/pure case.</p><hr><h2 id="_9-open-design-questions" tabindex="-1">9. Open Design Questions <a class="header-anchor" href="#_9-open-design-questions" aria-label="Permalink to “9. Open Design Questions”">​</a></h2><h3 id="_9-1-are-arrows-opaque-or-inspectable" tabindex="-1">9.1 Are arrows opaque or inspectable? <a class="header-anchor" href="#_9-1-are-arrows-opaque-or-inspectable" aria-label="Permalink to “9.1 Are arrows opaque or inspectable?”">​</a></h3><p>If arrows are fully inspectable, they resemble a typed intermediate representation. If they are opaque, handlers must provide all meaningful semantics. A hybrid model is likely preferable: the six combinators are inspectable; <code>app</code> boundaries are <strong>structurally transparent but not statically known</strong>.</p><p><code>ArrowApply</code> (<code>app</code>) makes the dynamic continuation an explicit first-class arrow value (a traversable data structure), not a hidden function closure as in monadic <code>bind</code>. This is a real representational difference: a handler can inspect, sandbox, or rewrite a received arrow <em>at runtime</em> before interpreting it. It is not, however, static transparency: if the arrow value is produced by runtime data, its shape is unknown at compile time and cannot be route-optimized. Note also that the opacity asymmetry is a representation choice, not inherent to either calculus — a free monad <code>Free f a</code> is fully inspectable data, and an arrow can be opaque if implemented as a closure. <code>ArrowApply ≅ Monad</code> (Hughes, LWY) means they share the same transparency <em>potential</em>; the structural-explicitness difference is what makes <code>app</code>&#39;s runtime inspectability cheaper to exploit.</p><p>For the Staged Arrow Engine backend (§9.6), the structural explicitness of <code>app</code> enables a three-way split of the kernel, not a two-way one:</p><ol><li><strong>Staged-resolvable fragment</strong> (no <code>app</code>, or <code>app</code> whose target is fixed at Stage 0) → spatial handler: full Stage 0 route optimization, zero-allocation execution.</li><li><strong>Finite-branch-space <code>app</code></strong> (<code>app</code> whose target set is provably finite and statically discoverable) → spatial handler with pre-compiled dispatch: Stage 0 pre-compiles every candidate sub-graph into a pre-allocated pool of flat Stage 1 chunks; runtime <code>app</code> becomes a zero-allocation pointer switch / indirect dispatch into the pool. This is the analogue of a jump table for arrow-valued data. Proving the branch space finite is the enabling analysis — trivial for first-order programs, potentially requiring abstract interpretation or type-based analysis when arrow values are computed by complex logic. Pre-compiling all branches multiplies the code-bloat trade-off (§4.2 of the SAE proposal); chunk eviction reintroduces dynamic memory management and must be balanced against the zero-allocation goal.</li><li><strong>Unbounded-branch-space <code>app</code></strong> (target set not provably finite, or dependent on unbounded runtime data schemas) → dynamic handler: live Stage 0 re-staging (sub-millisecond graph build + compile) or a conventional VM, exploiting the runtime transparency for inspection and sandboxing.</li></ol><p>The boundary is <em>provable-finite-branch-space</em>, not <code>app</code>-presence. This moves a large class of <code>app</code> usage — most conditional branching, pattern matching, and finite dispatch — from the dynamic handler into the spatial handler, leaving only genuinely unbounded dynamic structure to the fallback.</p><h3 id="_9-2-what-is-the-feedback-semantics-of-loop" tabindex="-1">9.2 What is the feedback semantics of <code>loop</code>? <a class="header-anchor" href="#_9-2-what-is-the-feedback-semantics-of-loop" aria-label="Permalink to “9.2 What is the feedback semantics of loop?”">​</a></h3><p>The kernel describes a feedback channel; the handler chooses the interpretation strategy. Two are standard:</p><ul><li><strong>Causal/strict</strong> — state carries forward across steps (state-machine reading; read-before-write is normal).</li><li><strong>Lazy/fixpoint</strong> — state is a fixpoint (Haskell <code>ArrowLoop</code> reading; read-before-write may be productive or ill-founded).</li></ul><p>Which semantics the reference handler implements, and how a language declares which it wants, is an implementation decision.</p><h3 id="_9-3-how-are-effects-typed" tabindex="-1">9.3 How are effects typed? <a class="header-anchor" href="#_9-3-how-are-effects-typed" aria-label="Permalink to “9.3 How are effects typed?”">​</a></h3><p>Effects could be encoded in the arrow&#39;s operations (the handler tracks them), or represented explicitly in the type: <code>Arrow&lt;Effects, A, B&gt;</code>.</p><h3 id="_9-4-what-are-the-tooling-protocols" tabindex="-1">9.4 What are the tooling protocols? <a class="header-anchor" href="#_9-4-what-are-the-tooling-protocols" aria-label="Permalink to “9.4 What are the tooling protocols?”">​</a></h3><p>If a language is a first-class value that participates in generic tooling, the tooling protocols (lex, parse, format, lint, typecheck, compile, ...) must be specified. What is the minimal protocol a language must implement to participate? How are protocol extensions composed?</p><h3 id="_9-5-are-languages-themselves-arrows" tabindex="-1">9.5 Are languages themselves arrows? <a class="header-anchor" href="#_9-5-are-languages-themselves-arrows" aria-label="Permalink to “9.5 Are languages themselves arrows?”">​</a></h3><p>One attractive possibility is <code>Language&lt;A, B&gt;</code> being an arrow-producing algebra rather than a fundamentally different kind of object. If successful, this removes the distinction between the object language and the meta-language entirely.</p><h3 id="_9-6-what-is-the-runtime-representation" tabindex="-1">9.6 What is the runtime representation? <a class="header-anchor" href="#_9-6-what-is-the-runtime-representation" aria-label="Permalink to “9.6 What is the runtime representation?”">​</a></h3><p>The source-level arrow might compile to graph, bytecode, closure, CPS, machine code, a VM instruction sequence, or a <strong>static spatial graph / interaction-net reduction</strong> (as in the Staged Arrow Engine proposal, where Stage 0 staging resolves dynamic control flow into a fixed, zero-allocation graph for stackless Stage 1 execution) — without changing the source semantics. The SAE backend is one handler interpretation among those listed above. Its coverage of the kernel is three-tiered (see §9.1): the staged-resolvable fragment and finite-branch-space <code>app</code> go to the spatial handler (the latter via pre-compiled dispatch tables, zero-allocation at runtime); unbounded-branch-space <code>app</code> is deferred to a dynamic handler (live re-staging or a conventional VM) that exploits <code>app</code>&#39;s runtime transparency for inspection and sandboxing.</p><hr><h2 id="_10-conclusion" tabindex="-1">10. Conclusion <a class="header-anchor" href="#_10-conclusion" aria-label="Permalink to “10. Conclusion”">​</a></h2><p>The central object is <code>A ~&gt; B</code>, an arrow representing a first-class computation. The central composition operator is <code>&gt;&gt;&gt;</code>, which constructs larger computations without requiring immediate execution. The central higher-order operator is <code>app</code>, which dynamically invokes a received arrow within the calculus. The central semantic mechanism is the <strong>handler</strong>, which interprets computational descriptions from outside.</p><p>The language is not Lambda Calculus with an arrow library. It is Arrow Calculus plus effects, handlers, and first-class languages. The conceptual shift is from <em>abstraction → application → substitution</em> toward <em>construction → composition → interpretation</em> — and the second-order shift is from a fixed language with external tooling toward a first-class language value participating in generic tooling protocols.</p><p>The kernel&#39;s purpose is not to execute programs directly. It provides the <strong>algebra from which programs are constructed</strong>. Handlers provide the semantics. Languages are first-class values that describe how programs work and participate in generic tooling.</p><p>The resulting tower is:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>arrows → programs → languages → generic tooling</span></span></code></pre></div><p>The unifying idea: <strong>make computation, then languages, first-class values, so the same compositional machinery applies recursively at every level.</strong></p><p>The language is not just the thing that runs the program.</p><p><strong>The language is another object the program can compute with.</strong></p><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li>Moggi — <em>Notions of Computation and Monads</em> (1991). Computational effects via monads; the monadic metalanguage. The precursor.</li><li>Hughes — <em>Generalising Monads to Arrows</em> (2000). Arrows as a generalization of monads; the computational abstraction.</li><li>Paterson — <em>A New Notation for Arrows</em> (2001). <code>proc</code> notation; introduced <code>loop</code> (feedback) and <code>returnA</code>.</li><li>Lindley, Wadler, Yallop — <em>The Arrow Calculus</em> (2008/2010, JFP). Arrows as a genuine typed metalanguage; the calculus foundation.</li><li>Lindley, Wadler, Yallop — <em>Idioms are Oblivious, Arrows are Meticulous, Monads are Promiscuous</em> (2011). Arrows in the monad/applicative/arrow landscape; classic arrows and the Arrow Calculus are equationally corresponding.</li><li>Lindley — <em>Algebraic Effects and Effect Handlers for Idioms and Arrows</em> (2014). Effects/handlers generalized to arrows; the bridge from algebraic effects to arrow-style computation.</li><li>Sanada — <em>Algebraic Effects and Handlers for Arrows</em> (2024). The semantic reference model: arrow handlers, operations, continuations; operational semantics (sound, adequate) and denotational semantics (handlers as homomorphisms between algebras of arrows).</li><li>Cimini — <em>A Calculus for Multi-language Operational Semantics</em> (2022, Springer; vision paper 2018). <code>λ^𝓛</code>, a typed λ-calculus where languages are first-class citizens. The theoretical foundation for languages as first-class values.</li><li>Haskell <code>Control.Arrow</code> — <code>ArrowLoop</code> as feedback; <code>ArrowApply</code> / <code>app</code>; <code>untilA</code> as a derived <code>while</code>-pattern over <code>loop</code> + <code>ArrowChoice</code>.</li><li>GHC User&#39;s Guide — arrow notation, <code>rec</code> construct, recursive arrows.</li></ul>`,177)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};